"""Reduce step-4 fixed-row attention; preserve each benchmark's declared selection split."""

import hashlib
import json
from pathlib import Path

ROOT = Path('/home/misha/lean_projects/transformer/experiments/basis_sparsemax')
FIELDS = ('mean_support_positions', 'mean_support_share', 'exact_zero_pair_share',
          'singleton_row_share', 'self_only_row_share', 'score_gap_gt_one_share',
          'normalized_entropy', 'mean_score_std', 'turnover_share')


def sha(path):
    hasher = hashlib.sha256()
    with path.open('rb') as source:
        for chunk in iter(lambda: source.read(1 << 20), b''):
            hasher.update(chunk)
    return hasher.hexdigest()


def mean(values):
    return None if not values else sum(values) / len(values)


def summarize(row):
    queries, layers = row['queries'], row['layers']
    wrong = [index for index, query in enumerate(queries) if not query['correct']]
    supported = [any(layer['answer_routes']['in_any_support'][index] for layer in layers.values())
                 for index in range(len(queries))]
    result = {key: row[key] for key in ('step', 'split', 'examples', 'rows_sha256',
                                      'teacher_forced_supervised_accuracy', 'diagnostic_probe')}
    result.update({'query_count': len(queries), 'wrong_queries': len(wrong),
                   'wrong_queries_with_answer_in_any_head': sum(supported[index] for index in wrong),
                   'wrong_queries_without_answer_in_any_head': sum(not supported[index] for index in wrong)})
    for kind in ('actual', 'shadow_sparsemax'):
        aggregate = {}
        for scope in ('all_rows', 'nontrivial_rows', 'supervised_rows'):
            heads = [head for layer in layers.values() for head in layer[kind][scope] if head['row_count']]
            aggregate[scope] = {field: mean([head[field] for head in heads if head[field] is not None])
                                for field in FIELDS}
            aggregate[scope]['turnover_changed_pairs'] = (None if not heads or heads[0]['turnover_changed_pairs'] is None
                                                         else sum(head['turnover_changed_pairs'] for head in heads))
        result[kind] = aggregate
    result['layers'] = {}
    for name, layer in layers.items():
        routes = layer['answer_routes']
        result['layers'][name] = {
            'wrong_queries_with_answer_in_any_head': sum(routes['in_any_support'][index] for index in wrong),
            'wrong_answer_maximum_weight_mean': mean([routes['maximum_weight'][index] for index in wrong]),
            'all_answer_maximum_weight_mean': mean(routes['maximum_weight']),
            'turnover_by_head': [head['turnover_share'] for head in layer['actual']['supervised_rows']],
            'xsa_self_only_below_epsilon_rows': layer.get('xsa_self_only_below_epsilon_rows')}
    return result


def trajectory(label):
    directory = ROOT / 'runs' / label
    result = json.loads((directory / 'result.json').read_text())
    description = json.loads((directory / 'experiment.json').read_text())['description']
    frames, first, last = [], None, None
    with (directory / 'attention.jsonl').open() as source:
        for line in source:
            row = json.loads(line)
            if first is None:
                first = row
            last = row
            frames.append(summarize(row))
    selection = 'validation' if description['benchmark']['select'] is None else f'validation/{description["benchmark"]["select"]}'
    history = {}
    with (directory / 'history.jsonl').open() as source:
        for line in source:
            observation = json.loads(line)
            history[observation['step']] = observation[selection]['sequence_accuracy']
    if frames[0]['step'] != 0 or frames[-1]['step'] != result['stop']['step']:
        raise ValueError(f'{label} lacks initialization or final attention')
    if len({frame['rows_sha256'] for frame in frames}) != 1:
        raise ValueError(f'{label} changed its validation rows')
    for frame in frames:
        frame['selection_sequence_accuracy'] = history.get(frame['step'])
    return {'description': description, 'stop': result['stop'],
            'selection': selection, 'best_sequence_accuracy': result['best'][selection]['sequence_accuracy'],
            'initial_heads': {name: {kind: layer[kind] for kind in ('actual', 'shadow_sparsemax')}
                              for name, layer in first['layers'].items()},
            'final_heads': {name: {kind: layer[kind] for kind in ('actual', 'shadow_sparsemax')}
                            for name, layer in last['layers'].items()},
            'trajectory': frames,
            'source': {str((directory / name).relative_to(ROOT)): sha(directory / name)
                       for name in ('experiment.json', 'result.json', 'history.jsonl', 'diagnostics.jsonl', 'attention.jsonl')}}
